class Solution {
public:
    vector<int> findThePrefixCommonArray(vector<int>& A, vector<int>& B) {
        int n = A.size();
        vector<int> C(n);
        unsigned long long maskA = 0, maskB = 0;
        for (int i = 0; i < n; i++) {
            maskA |= (1ULL << A[i]);
            maskB |= (1ULL << B[i]);
            C[i] = __builtin_popcountll(maskA & maskB);
        }
        return C;
    }
};
